ruleContent.content:
ChapterContent@js:
function p(e) {
    return e.split("").map(function (e) {
        return e.match(/[A-Za-z]/) ? (c = Math.floor(e.charCodeAt(0) / 97), k = (e.toLowerCase().charCodeAt(0) - 83) % 26 || 26, String.fromCharCode(k + (0 == c ? 64 : 96))) : e
    }).join("")
}
java.base64Decode(p(result))

ruleToc.chapterList:
@js:
let v = [],
		list = [];
JSON.parse(result).list.map($=>{

//分卷判定
		V = $.name;
		if(v[v.length-1]!=V&&!/^\s*$/.test(V)){
				v.push(V)
				list.push({
						name: '📖['+V+']📖',
						volume: true
					})
			}

$.bookChapters.map($=>{
		return list.push({
				name: $.name,
				url: `https://readbook-service-freebook.cread.com/cx/itf/chapterRead?bookId=${$.bookid}&chapterId=${$.id}`,
				info: `章节字数：${$.wordCount}　更新时间：${$.updateDate}`
			});
	});
});
v.length<2?list.filter($=>!$.volume):list

